import { z } from 'zod';
import countriesJson from '../../../content/countries.json';
import { IDEOLOGIES, RIVALS, SECTORS, type CountryId, type IdeologyId, type SectorId } from './ids';

/**
 * World content: content/countries.json, generated by tools/world/buildCountries.ts from public data
 * (rounded) with about twenty hand-tuned focus nations. Validated at load; a broken file fails `npm test`.
 */

const countrySchema = z.strictObject({
  id: z.string().regex(/^[A-Z]{3}$/, 'ids are ISO alpha-3 codes'),
  name: z.string().min(1),
  continent: z.string().min(1),
  subregion: z.string().min(1),
  /** Nominal GDP in US$ billion, rounded. */
  gdp: z.number().min(0),
  /** Population in millions, rounded. */
  population: z.number().min(0),
  /** Overall weight in world affairs, 0–100 (India is about 75). */
  power: z.number().min(0).max(100),
  /** A coarse outlook on India’s ideology scale; drives the “ideology match” in relations. */
  outlook: z.enum(IDEOLOGIES),
  /** 0–100: how readily this country picks a fight or makes threats. */
  aggression: z.number().min(0).max(100),
  /** Opening relation with India, −100…+100. */
  relation: z.number().min(-100).max(100),
  /** Sectors it is strong in; trade contracts in those sectors are likelier to be agreed. */
  strengths: z.array(z.enum(SECTORS)).min(1),
  /** Focus nations run the full utility-scoring AI; the rest drift and have random incidents. */
  focus: z.boolean(),
  /** Shares a land or close maritime border with India. */
  neighbour: z.boolean(),
});
export type CountryContent = {
  id: CountryId;
  name: string;
  continent: string;
  subregion: string;
  gdp: number;
  population: number;
  power: number;
  outlook: IdeologyId;
  aggression: number;
  relation: number;
  strengths: SectorId[];
  focus: boolean;
  neighbour: boolean;
};

const parsed = z.array(countrySchema).safeParse(countriesJson);
if (!parsed.success) {
  const issue = parsed.error.issues[0];
  throw new Error(`content/countries.json: ${issue?.path.join('.')}: ${issue?.message}`);
}

/** Every country, sorted by id (the order the monthly systems visit them in, which keeps games deterministic). */
export const COUNTRY_LIST: readonly CountryContent[] = parsed.data;
export const COUNTRY_CONTENT: Readonly<Record<CountryId, CountryContent>> = Object.fromEntries(
  COUNTRY_LIST.map((c) => [c.id, c]),
);
export const COUNTRY_IDS: readonly CountryId[] = COUNTRY_LIST.map((c) => c.id);
export const FOCUS_IDS: readonly CountryId[] = COUNTRY_LIST.filter((c) => c.focus).map((c) => c.id);

if (new Set(COUNTRY_IDS).size !== COUNTRY_IDS.length) throw new Error('content/countries.json: duplicate ids');
if (COUNTRY_CONTENT['IND']) throw new Error('content/countries.json: India is the player, not a country in the list');
for (const id of RIVALS) {
  if (!COUNTRY_CONTENT[id]?.focus) throw new Error(`content/countries.json: rival ${id} must be a focus nation`);
}
if (FOCUS_IDS.length < 15 || FOCUS_IDS.length > 25) {
  throw new Error(`content/countries.json: expected about 20 focus nations, found ${FOCUS_IDS.length}`);
}

export const isCountryId = (id: string): boolean => id in COUNTRY_CONTENT;
